void adjust_mtu_and_maxfraglen(unsigned int *mtu, int *maxfraglen,
                               unsigned int fragheaderlen,
                               struct sk_buff *skb,
                               struct rt6_info *rt,
                               bool pmtuprobe) {
    unsigned int new_mtu = 0;

    if (!ipv6_addr_is_multicast(&rt->rt6i_dst.addr)) {
        if (!skb) {
            new_mtu = rt->rt6i_mtu - fragheaderlen;
        } else {
            if (pmtuprobe) {
                new_mtu = rt->dst.dev->mtu - fragheaderlen;
            } else {
                new_mtu = rt->rt6i_dst_mtu - fragheaderlen;
            }
        }

        if (new_mtu < *mtu)
            *mtu = new_mtu;

        *maxfraglen = *mtu - fragheaderlen;
    }
}

void adjust_mtu_and_maxfraglen(unsigned int *mtu, int *maxfraglen, unsigned int fragheaderlen,
                               struct sk_buff *skb, struct rt6_info *rt, bool pmtuprobe) {
    if (!skb) {
        *mtu -= fragheaderlen;
    } else if (pmtuprobe) {
        *mtu = min(*mtu, rt->dst.dev->mtu);
    } else {
        *mtu = min(*mtu, rt->dst.path_mtu);
    }

    *maxfraglen = *mtu - fragheaderlen;
}

void adjust_mtu_and_maxfraglen(unsigned int *mtu, int *maxfraglen, unsigned int fragheaderlen,
                               struct sk_buff *skb, struct rt6_info *rt, bool pmtuprobe) {
    if (!rt_is_tunn(rt)) {
        if (!skb) {
            *mtu -= fragheaderlen;
        } else {
            *mtu = min(skb->dev->mtu, rt->dst.path_mtu);
        }
        *maxfraglen = *mtu - fragheaderlen;
    }
}

void adjust_mtu_and_fragment_length(unsigned int *mtu, int *maxfraglen,
                                    unsigned int fragheaderlen,
                                    struct sk_buff *skb,
                                    struct rt6_info *rt,
                                    bool pmtuprobe) {
    if (!skb) {
        *mtu -= fragheaderlen;
    } else {
        *mtu = skb->dev ? skb->dev->mtu : ip6_skb_dst_mtu(skb);
    }

    if (rt && rt->dst.dev && !ipv6_is_multicast(&rt->rt6i_dst.addr)) {
        if (pmtuprobe) {
            *mtu = rt->dst.metrics[RTAX_MTU - 1] ? : rt->dst.dev->mtu;
        } else {
            *mtu = min(*mtu, rt->dst.metrics[RTAX_MTU - 1]);
        }
    }

    *maxfraglen = *mtu - fragheaderlen;
}

void adjust_mtu_and_maxfraglen(unsigned int *mtu, int *maxfraglen,
                               unsigned int fragheaderlen, struct sk_buff *skb,
                               struct rt6_info *rt, bool pmtuprobe) {
    if (!skb) {
        *mtu -= fragheaderlen;
    } else {
        if (!pmtuprobe && rt->rt6i_dst_mtu_cached) {
            *mtu = rt->rt6i_dst_mtu_cached;
        }
    }

    *maxfraglen = *mtu - fragheaderlen;
}
